CREATE TABLE Account ( AccountId TEXT PRIMARY KEY, AccountName TEXT, ImageId TEXT , GroupId INTEGER , ParentAccountId TEXT , PredefinedType Text, IsLocked INTEGER, CreationOrder INTEGER, WalletId TEXT, CreatedAt INTEGER, UpdatedAt INTEGER, Editor TEXT, EditorDeviceId TEXT, Tag TEXT, RevId TEXT );
CREATE TABLE Wallet ( WalletId TEXT PRIMARY KEY, WalletName TEXT, ImageId TEXT , CurrencyTypeId INTEGER, TravelModeEventId TEXT, CreatedAt INTEGER, UpdatedAt INTEGER, Editor TEXT, EditorDeviceId TEXT, Owner TEXT, Participators TEXT, Tag TEXT, RevId TEXT , WalletType Text);
CREATE TABLE AccTransaction ( AccTransactionId TEXT PRIMARY KEY, AccountId TEXT, AccountName Text, AccountImageId Text, AccountGroupId Integer, RegFaDate Text, RegGeDate INTEGER, Note Text, Amount INTEGER, ImageId Text, ReminderFaDate Text, ReminderGeDate INTEGER , BankId TEXT, BankName Text, EventId TEXT, EventName Text, ProjectId TEXT, ProjectName Text, PeopleName Text, PeopleIds Text, StuffId TEXT, StuffName Text, GeneralReferenceId TEXT, MasterAccTransactionId TEXT, PayedDebtAmount INTEGER, DebtIsFinished INTEGER, Tag Text, WalletId TEXT, WalletName Text, CreatedAt INTEGER, UpdatedAt INTEGER, Editor TEXT, EditorDeviceId TEXT, RevId TEXT , TerminalId TEXT, TerminalName TEXT);
CREATE TABLE Project ( ProjectId TEXT PRIMARY KEY, ProjectName TEXT, ImageId TEXT , WalletId TEXT, CreatedAt INTEGER, UpdatedAt INTEGER, Editor TEXT, EditorDeviceId TEXT, Tag TEXT, RevId TEXT );
CREATE TABLE Bank ( BankId TEXT PRIMARY KEY, BankName TEXT, ImageId TEXT , BankType INTEGER, BankAccountNo TEXT, BankCardNo TEXT, Note TEXT, Sheba TEXT, BankProfileId TEXT, Provider TEXT, DepositNumber TEXT, BankKey TEXT, Balance TEXT, WalletId TEXT, CreatedAt INTEGER, UpdatedAt INTEGER, Editor TEXT, EditorDeviceId TEXT, Tag TEXT, RevId TEXT , IsConnectedToBank INTEGER, BankToken TEXT, ExpirationDateToken TEXT);
